          this.tick === 619 &&
          entity.id === 286 &&
          entity.house === House.USSR &&
          entity.type === UnitType.I_E1 &&
          entity.mission === Mission.MOVE &&
          entity.missionQueue === null &&
          entity.cell.cx === 43 &&
          entity.cell.cy === 60;
